from users.validate import validate_email


def import_users(csv_text: str) -> dict:
    """Import users from CSV text (see README)."""
    imported = []
    rejected = []
    seen = set()

    for line_no, line in enumerate(csv_text.splitlines(), start=1):
        if line_no == 1:
            continue  # header
        if not line.strip():
            continue  # blank line, skipped but counted

        parts = line.split(",", 1)
        if len(parts) == 2:
            name, email = parts
        else:
            name = parts[0] if parts else ""
            email = ""

        if not validate_email(email):
            rejected.append({"line": line_no, "email": email, "reason": "invalid_email"})
            continue

        lower_email = email.lower()
        if lower_email in seen:
            rejected.append({"line": line_no, "email": email, "reason": "duplicate"})
            continue

        seen.add(lower_email)
        imported.append({"name": name, "email": lower_email})

    return {"imported": imported, "rejected": rejected}
